import {namedOrder} from './ui-order.js';
import {broadsideControls} from './broadside.js';
import {cargoEditor} from './cargo-editor.js';
import {gunUnits,catalogueItem} from './cargo-catalogue.js';
import {gunWeight,weightText,legacyNote} from './load.js';
import {catalogue,families,sides,slotsFor,gunSpec,armamentFor,allowedTypes,ammoAllowed,shotNotes} from './weapons.js';

export function armamentFields(a,prefix){return `<fieldset class="mount-fields"><legend>Gun slots</legend><p class="subtle">Port and starboard are broadsides; bow and stern are chase positions. Total slots define gun capacity (maximum 100).</p><div class="slot-counts">${sides.map(side=>`<label>${side}<input id="${prefix}-${side}" type="number" min="0" max="100" step="1" required value="${a.layout[side]}"></label>`).join('')}</div>${[['broadsideTypes','Broadside gun families'],['chaseTypes','Chase gun families']].map(([key,label])=>`<fieldset><legend>${label}</legend><div class="family-options">${families.map((family,i)=>`<label><input type="checkbox" id="${prefix}-${key}-${i}" ${a[key].includes(family)?'checked':''}>${family}</label>`).join('')}</div></fieldset>`).join('')}</fieldset>`;}

export function batteryMap(s,escape){const slots=slotsFor(s);const battery=side=>`<div class="battery battery-${side.toLowerCase()}" aria-label="${side} gun slots"><span class="battery-label">${side}</span>${slots.filter(slot=>slot.side===side).map(slot=>{const spec=slot.gun&&gunSpec(slot.gun),state=!spec?'Empty':slot.gun.condition!=='operational'?slot.gun.condition:!s.stations['Gun Deck'].hp?'Blocked':slot.gun.loaded?'Ready':'Reload';return `<button data-slot="${slot.id}" class="gun-token ${state==='Ready'?'ready':state==='Empty'?'vacant':state==='Reload'?'':'disabled-gun'}" aria-label="${escape(slot.name)}, ${spec?escape(spec.name):'empty'}, ${state}"><span>${spec?spec.code:'+'}</span><small>${spec?spec.poundage+'lb':'Empty'}</small><small>${state==='Empty'?'slot':state}</small></button>`;}).join('')}${!slots.some(slot=>slot.side===side)?'<small>None</small>':''}</div>`;return {bow:battery('Bow'),port:battery('Port'),starboard:battery('Starboard'),stern:battery('Stern')};}

export function armamentsPanel(s,admin,escape,ammoChoices={}){const a=armamentFor(s),slots=slotsFor(s);return `<h2>Guns & loadout</h2><p>${s.guns.length} installed / ${slots.length} slots · LG long gun · CA carronade · HW howitzer · SW swivel</p><p class="subtle">Reload after one uninterrupted turn. Shot effects and crew shortages are adjudicated at the table. Ammunition size compatibility remains a GM check. Catalogue rounds retain their size and cargo units when loaded.</p>${admin?`<details class="card"><summary>Configure slots and mounting restrictions</summary><form id="armament-form" class="stack">${armamentFields(a,'mount')}<button class="primary">Save slot layout</button><p class="subtle">Occupied slots cannot be removed or made incompatible. Move or remove their guns first.</p></form></details>`:''}${sides.map(side=>`<h3 class="battery-heading">${side}${['Bow','Stern'].includes(side)?' chase':' broadside'} · ${a.layout[side]} slots</h3>${['Port','Starboard'].includes(side)?broadsideControls(s,side,escape,ammoChoices[side]):''}<div class="gun-cards">${slots.filter(v=>v.side===side).map(slot=>{const g=slot.gun,spec=g&&gunSpec(g);return `<div class="card stack" id="slot-${slot.id}"><div class="card-head"><h3>${escape(slot.name)}</h3><span class="gun-badge">${spec?spec.code+' · '+spec.poundage+'lb':'Empty'}</span></div>${spec?`<strong>${escape(spec.name)}</strong><p>${catalogueItem('gun-'+spec.id)?.rarity??'Unknown rarity'} · ${spec.weight} · ${spec.damage} damage${spec.family==='Swivel Gun'?' to crew only':''} · ${spec.minRange?spec.minRange+'–':''}${spec.range} hexes · ${spec.crew} crew · ${spec.cost}gp reference cost</p><p>Cargo load: ${weightText(gunWeight(g))}</p>${!Object.hasOwn(g,'cargoUnits')?legacyNote(g.cargoWeight,escape):''}${admin?`<details><summary>Edit gun cargo units</summary><label>Cargo units override<input id="gun-weight-${g.id}" type="number" min="0" max="1000000000000" step="any" value="${g.cargoUnits??''}" placeholder="GM default: ${gunUnits(spec)}"></label><button data-gun-weight="${g.id}">Save gun cargo units</button><p class="subtle">Blank uses the GM formula. Saving confirms the new cargo-unit setting.</p></details>`:''}${g.loaded?`<details><summary>Loaded round: ${weightText(g.loadedCargo?.cargoUnits)} · classify / edit</summary><form class="loaded-cargo-form cargo-editor" data-loaded-gun="${g.id}">${cargoEditor({...g.loadedCargo,name:g.loaded,unitWeight:g.loadedUnitWeight??g.loadedCargo?.unitWeight},escape,{loaded:true})}<button>Save loaded round</button></form></details>`:''}<p>${g.loaded?escape(g.loaded)+' loaded':'No round loaded'} · ${escape(g.condition)} · ${g.assigned} / ${spec.crew} crew</p>${g.assigned<spec.crew?'<p class="subtle">Understaffed: confirm crew at the table.</p>':''}<p class="subtle">${shotNotes(g.loaded)}</p><div class="actions">${g.loaded?`<button class="primary" data-fire="${g.id}" ${g.condition!=='operational'||!s.stations['Gun Deck'].hp?'disabled':''}>Fire ${escape(slot.name)}</button>`:`<select aria-label="Ammunition for ${escape(slot.name)}" id="ammo-${g.id}">${namedOrder(s.inventory.filter(i=>i.quantity>0&&ammoAllowed(g,i))).map(i=>`<option value="${escape(i.id)}">${escape(i.name)} (${i.quantity})</option>`).join('')}</select><button data-reload="${g.id}" ${g.condition!=='operational'||!s.stations['Gun Deck'].hp||!s.stations['Powder Dock'].hp||!s.inventory.some(i=>i.quantity>0&&ammoAllowed(g,i))?'disabled':''}>Complete reload</button>`}</div><details><summary>Condition & crew</summary><label>Condition<select data-condition="${g.id}">${['operational','disabled','destroyed'].map(n=>`<option ${g.condition===n?'selected':''}>${n}</option>`).join('')}</select></label><div class="actions"><label>Assigned crew<input id="assign-${g.id}" type="number" min="0" max="${s.maxCrew}" value="${g.assigned}"></label><button data-assign="${g.id}">Assign</button></div></details>`:'<p>No cannon installed.</p>'}${admin?`<details><summary>${spec?'Change or remove cannon':'Install cannon'}</summary><label>Cannon<select id="refit-${slot.id}"><option value="">Empty slot</option>${catalogue.filter(t=>allowedTypes(a,side).includes(t.family)).map(t=>`<option value="${t.id}" ${g?.gunType===t.id?'selected':''}>${escape(t.name)}</option>`).join('')}</select></label><button data-refit="${slot.id}">Apply loadout change…</button><p class="subtle">GM configuration: no gold or cannon inventory is deducted. Replacements start operational and unloaded; old loaded shot returns to stores and crew become unassigned.</p>${spec?`<label>Move this cannon to an empty slot<select id="move-${slot.id}">${slots.filter(v=>!v.gun&&allowedTypes(a,v.side).includes(spec.family)).map(v=>`<option value="${v.id}">${escape(v.name)}</option>`).join('')}</select></label><button data-move-gun="${slot.id}">Move cannon</button>`:''}</details>`:''}</div>`;}).join('')}</div>`).join('')}`;}
